/**
 * Fluent builder for creating configured tokenizers
 */
class TokenizerBuilder {
  private val normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val validators: mutable.ListBuffer[String => Boolean] = mutable.ListBuffer.empty
  private val metadata: mutable.Map[String, Any] = mutable.Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: String => Boolean): TokenizerBuilder = {
    validators += validator
    this
  }

  def withMetadata(key: String, value: Any): TokenizerBuilder = {
    metadata(key) = value
    this
  }

  def withMetadata(entries: Map[String, Any]): TokenizerBuilder = {
    metadata ++= entries
    this
  }

  def build(): String => Token = {
    val normalizersList = normalizers.toList
    val validatorsList = validators.toList
    val metadataMap = metadata.toMap

    (value: String) => {
      validatorsList.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      val normalized = normalizersList.foldLeft(value) { (acc, norm) =>
        norm(acc)
      }

      Token(normalized, TokenType.String, metadataMap)
    }
  }
}

/**
 * Companion object with utility functions for tokenization
 */
object Tokenizer {
  /**
   * Tokenize a single value using the universal tokenizer
   */
  def tokenize(value: String): Option[Token] = {
    val tokenizer = new UniversalTokenizer()
    tokenizer.tokenize(value)
  }

  /**
   * Convert a string value to a token with position information
   */
  def toToken(value: String, position: Int): Option[Token] = {
    tokenize(value).map(_.withMetadata("position", position))
  }

  /**
   * Tokenize multiple values and return list of tokens
   */
  def tokenizeBatch(values: Seq[String]): List[Token] = {
    values.zipWithIndex.flatMap { case (value, index) =>
      toToken(value, index)
    }.toList
  }

  /**
   * Tokenize a value and add metadata to the resulting token
   */
  def tokenizeWithMetadata(value: String, metadata: Map[String, Any]): Option[Token] = {
    tokenize(value).map(_.withMetadata(metadata))
  }

  /**
   * Create a new TokenizerBuilder
   */
  def builder(): TokenizerBuilder = new TokenizerBuilder()
}
